         geometry_msgs::Twist twist;
         twist.linear.x = 2 * sqrt(pow(tf.transform.translation.x,2) + pow(tf.transform.translation.y,2));
         twist.angular.z = 2 * atan2(tf.transform.translation.y,tf.transform.translation.x);
         pub.publish(twist);
      }
      catch(const std::exception& e)
      {
         // std::cerr << e.what() << '\n';
         ROS_INFO("tf_turtlesim_sub 错误提示:%s",e.what());
      }
      rate.sleep();
      ros::spinOnce();
    }
    return 0;
}

